from tests_src import T, Q2, TF

T(27, "27-7", "Nurse, Traveller and Business Owner", "Information Report", [
"Mary Seacole was born in 1805 in Kingston, a busy port city in Jamaica. Her father was a Scottish soldier, and her mother was a healer who used herbs and traditional remedies to help people who were unwell. Her mother also ran a boarding house, which was a kind of small hotel where visitors paid to stay. Mary grew up watching and helping, and she soon became skilled at looking after the guests and at caring for anyone who needed a hand.",
"Mary was curious about the world and keen to see more of it. When she was young, she visited England, and later she travelled to islands such as the Bahamas, Haiti and Cuba. On these journeys she bought spices, pickles and jams to sell back in Jamaica, which showed that she had a real talent for business. In 1851 she travelled to Panama, in Central America, where she helped to run a restaurant and gave out medicines to people who asked for them.",
"In 1855, soldiers from Britain were staying in the Crimea, a region beside the Black Sea and a very long way from home. Mary wanted to help them. She went to London and offered to work as a nurse, but her offer was turned down. Mary did not give up. She paid for her own journey and sailed to the Crimea with a man named Thomas Day.",
"Near the town of Balaclava, Mary and Thomas opened a place called the British Hotel. It was not a hotel in the usual sense. It was a hut made of metal sheets, and it worked as a storehouse, a canteen and a resting place all in one. Soldiers could rest there and buy hot food, drinks and supplies. Mary also visited soldiers who needed care and sold medicines to them. They were so fond of her that they called her \u201cMother Seacole\u201d.",
"When she returned to Britain, Mary wrote the story of her life. Her book, Wonderful Adventures of Mrs Seacole in Many Lands, was published in 1857 and became a best seller, so many people read about her adventures. An autobiography is a life story written by the person who lived it, and this one is often described as the first written in Britain by a Black woman. For many years afterwards, however, her name was not widely remembered.",
"Today, Mary Seacole is celebrated again. In 2004, she was voted the greatest Black Briton in a national poll. In 2016, a statue of her was unveiled in the gardens of St Thomas\u2019 Hospital in London, a place where people are cared for every day. She is remembered as a traveller, a business owner and a carer with the courage to keep going when others said no. Her story has been taught in schools since 2007.",
], [
 dict(d="2b",k="mc",m=1,q="Where was Mary Seacole born?",opts=["London, England","Kingston, Jamaica","Panama, Central America","Balaclava, the Crimea"],a="B"),
 dict(d="2b",k="short",m=2,q="Give two things that Mary\u2019s mother did.",a="She was a healer (who used herbs and remedies); she ran a boarding house.",g="1 mark for each. Accept healing / helping people who were unwell / using herbs, and running a boarding house or small hotel. Max 2."),
 dict(d="2a",k="find",m=1,q="Find and copy one word from paragraph 2 that shows Mary wanted to learn about the world.",a="curious",g="Accept \u201ccurious\u201d or \u201ckeen\u201d."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does the phrase \u201cturned down\u201d mean?",opts=["Made quieter","Written down","Refused","Passed on"],a="C"),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Mary\u2019s book was published.","Mary went to Panama.","Mary opened the British Hotel.","Mary offered to work as a nurse."],a=[4,1,3,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Mary\u2019s father was a Scottish soldier.","Mary sold her spices and jams in Cuba.","The British Hotel was a hut made of metal sheets.","The statue of Mary stands in Jamaica."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Why did Mary pay for her own journey to the Crimea?",a="Because her offer to work as a nurse had been turned down, so nobody else sent her.",g="Accept any answer linked to her offer being refused / no one else would take or pay for her."),
 dict(d="2d",k="short",m=1,q="Why do you think the soldiers called her \u201cMother Seacole\u201d?",a="Because she looked after them and cared for them, as a mother would.",g="Accept any answer about her caring for, feeding or helping them, or about them being fond of her. Do not accept \u201cbecause she was old\u201d."),
 dict(d="2d",k="short",m=1,q="In paragraph 4, the writer says the British Hotel \u201cwas not a hotel in the usual sense\u201d. How was it different from a usual hotel?",a="It was a hut where soldiers could rest and buy food, drinks and supplies, not a place where guests paid to stay.",g="Accept any answer saying it was a hut / shop / rest place rather than a building for guests to stay in (paragraph 1 explains a boarding house is where visitors paid to stay)."),
 dict(d="2b",k="short",m=1,q="What did Mary do after she returned to Britain?",a="She wrote the story of her life / a book.",g="Accept: wrote a book / wrote her autobiography."),
 dict(d="2g",k="short",m=1,q="The writer says that Mary \u201cis celebrated again\u201d. What does the word \u201cagain\u201d tell you?",a="That Mary had been celebrated before, then not remembered for many years, and is now praised once more.",g="Accept any answer showing she was known or praised in the past, then forgotten, then remembered."),
 dict(d="2c",k="mc",m=1,q="Which is the best heading for paragraph 4?",opts=["Mary\u2019s life in Panama","A book for children","Mary\u2019s childhood in Jamaica","A hut that helped soldiers"],a="D"),
 dict(d="2d",k="short",m=1,q="Why do you think a statue of Mary was put in the gardens of a hospital?",a="Because she cared for people, and a hospital is a place where people are cared for.",g="Accept any answer linking Mary\u2019s caring or nursing to the hospital."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["A Jamaican traveller ran a business, cared for soldiers and is now widely honoured.","A Scottish soldier wrote a book about his life in Jamaica.","A hotel owner spent all her life in one town in Jamaica.","A nurse was welcomed by everyone she asked for work."],a="A"),
])

T(28, "28-7", "The Doctor Who Went to Space", "Information Report", [
"On the 12th of September 1992, the space shuttle Endeavour roared away from its launch pad carrying seven astronauts. Among them was Dr Mae Jemison, who became the first African American woman to travel into space. Her journey to that launch had begun many years earlier.",
"Mae was born in Alabama in 1956 and moved to Chicago as a young child. Her parents encouraged her to be curious, and she spent hours reading library books and visiting museums. She loved science and worked hard at school. At the age of sixteen, she started university at Stanford, where she studied chemical engineering, which is the use of chemistry and machines to make useful things, alongside African American studies. She then trained as a doctor at Cornell University, qualifying in 1981.",
"Being a doctor took Mae far from home. She joined the Peace Corps, an American organisation that sends volunteers overseas to help local communities. For around two years, she worked as a medical officer in Sierra Leone and Liberia, two countries in West Africa, helping to look after the health of the people who worked there.",
"When Mae returned home, she still had a dream of travelling into space. She applied to NASA, the American space agency, and she was one of only fifteen people chosen from about two thousand applicants. After that came years of training, because astronauts must learn how to work safely in a spacecraft and how to cope with life without gravity.",
"On Endeavour, Mae\u2019s job was to be a mission specialist, someone who carries out the scientific work on board. The shuttle circled the Earth for nearly eight days, and the seven crew members took part in more than forty experiments. The shuttle carried a science laboratory in its cargo area, where much of the work took place. Mae helped with studies that showed how living things behave without gravity. One looked at how bone cells change in space. Another looked at how frog eggs grow and develop far above the ground. She also worked on ways of helping astronauts who feel dizzy and unwell when they first arrive in space. Studies like these can help scientists to understand how to keep people healthy on long journeys.",
"After she left NASA in 1993, Mae kept working to help others learn. She taught at Dartmouth College, and in 1994 she started The Earth We Share, a science camp that welcomed young people from different countries. She also took charge of a project called 100 Year Starship, which explores how people might one day travel to other stars.",
"Since then, she has given many talks about science and space. Mae Jemison\u2019s story shows how curiosity, hard work and an early love of learning can carry a person a very long way, even beyond the sky.",
], [
 dict(d="2b",k="mc",m=1,q="What was the name of the space shuttle that Mae travelled on?",opts=["Discovery","Atlantis","Endeavour","Columbia"],a="C"),
 dict(d="2b",k="short",m=1,q="Which city did Mae move to as a young child?",a="Chicago.",g="Accept Chicago only."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word \u201ccurious\u201d mean?",opts=["Full of energy","Keen to find things out","Good at sport","Quiet and shy"],a="B"),
 dict(d="2b",k="short",m=2,q="Give two things Mae did as a child that helped her to learn about science.",a="She read library books; she visited museums.",g="1 mark for each. Max 2."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Mae worked in Sierra Leone and Liberia.","Endeavour rose into space.","Mae studied at Stanford.","Mae qualified as a doctor."],a=[3,4,1,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Mae was born in Chicago.","The Peace Corps sends volunteers overseas.","NASA chose about two thousand people from the applicants.","Mae was in space for nearly eight days."],a=["F","T","F","T"],g=TF),
 dict(d="2a",k="find",m=1,q="Find and copy the words in paragraph 5 that explain what a mission specialist is.",a="someone who carries out the scientific work on board",g="Accept \u201csomeone who carries out the scientific work on board\u201d."),
 dict(d="2d",k="short",m=1,q="How can you tell that Mae did very well at school? Use paragraph 2.",a="She started university at the age of sixteen, which is younger than most students.",g="Accept: she went to Stanford / university at sixteen."),
 dict(d="2d",k="short",m=1,q="Paragraph 3 says being a doctor \u201ctook Mae far from home\u201d. How did it do this?",a="She used her training to work as a medical officer in West Africa (Sierra Leone and Liberia).",g="Accept any answer saying she worked abroad / in Africa as a doctor."),
 dict(d="2d",k="short",m=1,q="Why was it a great achievement for Mae to be chosen by NASA?",a="Only fifteen people were chosen from about two thousand applicants, so very few succeed.",g="Accept any answer that mentions how few people were chosen."),
 dict(d="2d",k="short",m=1,q="What were scientists on the mission trying to find out?",a="How living things (such as bone cells and frog eggs) behave / change without gravity.",g="Accept any answer about the effects of space or a lack of gravity on living things or the body."),
 dict(d="2g",k="short",m=1,q="The last paragraph says curiosity and hard work can carry a person \u201ceven beyond the sky\u201d. What does the writer mean?",a="They helped Mae reach space, which is beyond the sky / further than most people ever go.",g="Accept any answer that links this to Mae travelling into space."),
 dict(d="2c",k="mc",m=1,q="Which is the best heading for paragraph 6?",opts=["Mae\u2019s work after NASA","Learning to be an astronaut","Mae\u2019s time in Africa","Life aboard Endeavour"],a="A"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Space shuttles are very fast and can circle the Earth in eight days.","A doctor and scientist followed her curiosity all the way into space, and then helped others to learn.","Frog eggs and bone cells can grow only in space.","Chicago is a good place to learn about science."],a="B"),
])

T(29, "29-7", "A Licence Earned in France", "Recount (Historical)", [
"Bessie Coleman was born in Texas on the 26th of January 1892 and grew up in a busy, hard-working family of thirteen children. In 1915, she moved to Chicago, a big city in the north of the United States, to look for better opportunities. There she lived with two of her brothers and worked as a manicurist, which means someone who looks after people\u2019s hands and nails.",
"Chicago was a busy city full of new ideas, and before long Bessie had a big one of her own. One of her brothers had spent time in France, and he told her that women there were learning to fly aeroplanes. Bessie was determined to become a pilot too.",
"There was a problem, however. At that time, no flying school in the United States would accept her, because she was Black and because she was a woman. Bessie did not give up. It was a hard thing to hear, but she looked for another way. Robert Abbott, who published a newspaper called the Chicago Defender, suggested that she try France instead. So Bessie began French lessons in the evenings and saved money from her work to pay for the journey.",
"In November 1920, Bessie sailed across the Atlantic Ocean to France. She joined the Caudron Brothers\u2019 School of Aviation in Le Crotoy, a small town by the sea. Every day she studied how aeroplanes work as well as how to fly them. Her training aeroplane was a biplane, which has two wings, one above the other, and it was steered with a tall stick and a bar worked by the pilot\u2019s feet. Learning all this in a new country, in a language she had only recently learned, took courage and hard work.",
"On the 15th of June 1921, Bessie\u2019s efforts paid off. An international organisation called the F\u00e9d\u00e9ration A\u00e9ronautique Internationale gave her a pilot\u2019s licence, which is an official document saying that a person is allowed to fly. The organisation keeps the official rules and records for flying around the world. She had completed her training in about seven months, and she had become the first African American woman to earn a pilot\u2019s licence.",
"Bessie returned to New York in September 1921, where newspaper reporters were waiting to greet her. She was eager to share her new skill, so she began giving flying displays in which she performed loops and figure eights high above the crowds. Reporters wrote about her, and large audiences came to watch.",
"Bessie also had firm beliefs about who should be allowed to see her shows. She refused to take part in any event that kept Black people out, insisting that everyone should be welcome. Having found the first doors closed to her, she used her fame to open others for the people who came after her.",
], [
 dict(d="2b",k="mc",m=1,q="How many children were in Bessie\u2019s family?",opts=["Ten","Thirteen","Sixteen","Twenty"],a="B"),
 dict(d="2b",k="short",m=1,q="What job did Bessie do in Chicago?",a="She was a manicurist.",g="Accept manicurist / looking after people\u2019s hands and nails."),
 dict(d="2a",k="mc",m=1,q="In paragraph 2, what does the word \u201cdetermined\u201d mean?",opts=["Worried","Puzzled","Tired","Firmly decided"],a="D"),
 dict(d="2a",k="find",m=1,q="Find and copy the one word in paragraph 4 that names the kind of aeroplane Bessie learned to fly in.",a="biplane",g="Accept \u201cbiplane\u201d only."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Bessie sailed to France.","Bessie moved to Chicago.","Bessie was given her pilot\u2019s licence.","Bessie began French lessons."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Bessie was born in Texas.","Bessie learned to fly at a school in Chicago.","An international organisation gave Bessie her licence.","Bessie came back to New York in 1920."],a=["T","F","T","F"],g=TF),
 dict(d="2d",k="short",m=1,q="Why did Bessie decide to learn French?",a="Because she planned to train as a pilot in France, where she could be accepted.",g="Accept any answer linking French to going to France to train / because no US school would accept her."),
 dict(d="2b",k="short",m=1,q="Which organisation gave Bessie her pilot\u2019s licence?",a="The F\u00e9d\u00e9ration A\u00e9ronautique Internationale.",g="Accept the name (allow spelling errors) or \u201can international organisation\u201d."),
 dict(d="2g",k="short",m=1,q="Why do you think the writer uses the short sentence \u201cBessie did not give up.\u201d in paragraph 3?",a="To make the reader notice how determined she was after being refused.",g="Accept any answer about stressing her determination or courage."),
 dict(d="2d",k="short",m=2,q="What does Bessie\u2019s response to being refused by American flying schools tell you about her? Give evidence from the text.",a="She was determined / brave / hard-working, because she learned French, saved money and sailed to another country to train.",g="1 mark for a suitable quality (determined, brave, hard-working, not easily beaten). 1 mark for evidence (French lessons, saving money, sailing to France, studying in a new country)."),
 dict(d="2d",k="short",m=1,q="What does paragraph 7 tell you about Bessie\u2019s beliefs?",a="She believed that everyone, whatever their skin colour, should be treated fairly / be welcome at her shows.",g="Accept any answer about fairness, equality or everyone being welcome."),
 dict(d="2c",k="mc",m=1,q="Which is the best heading for paragraph 4?",opts=["Learning to fly in France","A busy family in Texas","Returning to New York","Rules for pilots"],a="A"),
 dict(d="2e",k="short",m=2,q="How might Bessie\u2019s success have affected other people who wanted to fly? Explain your answer using the text.",a="It might have encouraged them / shown them that it was possible, because Bessie earned a licence even though the first doors were closed to her.",g="1 mark for a sensible prediction (inspired, encouraged, gave hope). 1 mark for a reason from the text (she was the first, she succeeded despite being refused, she used her fame to help others)."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Bessie Coleman lived in Texas and Chicago all her life.","Bessie Coleman worked as a manicurist and taught French.","Bessie Coleman overcame being turned away, learned to fly in France and became a celebrated pilot.","Bessie Coleman built the first biplane in Le Crotoy."],a="C"),
])
